const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
const a = tok.slice(2, 2 + n);
const tree = new Array(4 * n).fill(0);
const lazy = new Array(4 * n).fill(0);
function build(node, lo, hi) {
  if (lo === hi) { tree[node] = a[lo]; return; }
  const mid = (lo + hi) >> 1;
  build(2 * node, lo, mid);
  build(2 * node + 1, mid + 1, hi);
  tree[node] = tree[2 * node] + tree[2 * node + 1];
}
function apply(node, lo, hi, v) {
  tree[node] += v * (hi - lo + 1);
  lazy[node] += v;
}
function push(node, lo, hi) {
  if (lazy[node] !== 0) {
    const mid = (lo + hi) >> 1;
    apply(2 * node, lo, mid, lazy[node]);
    apply(2 * node + 1, mid + 1, hi, lazy[node]);
    lazy[node] = 0;
  }
}
function update(node, lo, hi, l, r, v) {
  if (r < lo || hi < l) return;
  if (l <= lo && hi <= r) { apply(node, lo, hi, v); return; }
  push(node, lo, hi);
  const mid = (lo + hi) >> 1;
  update(2 * node, lo, mid, l, r, v);
  update(2 * node + 1, mid + 1, hi, l, r, v);
  tree[node] = tree[2 * node] + tree[2 * node + 1];
}
function query(node, lo, hi, l, r) {
  if (r < lo || hi < l) return 0;
  if (l <= lo && hi <= r) return tree[node];
  push(node, lo, hi);
  const mid = (lo + hi) >> 1;
  return query(2 * node, lo, mid, l, r) + query(2 * node + 1, mid + 1, hi, l, r);
}
build(1, 0, n - 1);
const out = [];
let pos = 2 + n;
for (let i = 0; i < q; i++) {
  if (tok[pos] === 1) {
    update(1, 0, n - 1, tok[pos + 1] - 1, tok[pos + 2] - 1, tok[pos + 3]);
    pos += 4;
  } else {
    out.push(query(1, 0, n - 1, tok[pos + 1] - 1, tok[pos + 2] - 1));
    pos += 3;
  }
}
console.log(out.join("\n"));

