import java.io.*;
import java.util.*;

public class Main {
    static long[] tree, lazy, a;

    static void build(int node, int lo, int hi) {
        if (lo == hi) { tree[node] = a[lo]; return; }
        int mid = (lo + hi) / 2;
        build(2 * node, lo, mid);
        build(2 * node + 1, mid + 1, hi);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    static void apply(int node, int lo, int hi, long v) {
        tree[node] += v * (hi - lo + 1);
        lazy[node] += v;
    }

    static void push(int node, int lo, int hi) {
        if (lazy[node] != 0) {
            int mid = (lo + hi) / 2;
            apply(2 * node, lo, mid, lazy[node]);
            apply(2 * node + 1, mid + 1, hi, lazy[node]);
            lazy[node] = 0;
        }
    }

    static void update(int node, int lo, int hi, int l, int r, long v) {
        if (r < lo || hi < l) return;
        if (l <= lo && hi <= r) { apply(node, lo, hi, v); return; }
        push(node, lo, hi);
        int mid = (lo + hi) / 2;
        update(2 * node, lo, mid, l, r, v);
        update(2 * node + 1, mid + 1, hi, l, r, v);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    static long query(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return 0;
        if (l <= lo && hi <= r) return tree[node];
        push(node, lo, hi);
        int mid = (lo + hi) / 2;
        return query(2 * node, lo, mid, l, r) + query(2 * node + 1, mid + 1, hi, l, r);
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        a = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            a[i] = (long) in.nval;
        }
        tree = new long[4 * n];
        lazy = new long[4 * n];
        build(1, 0, n - 1);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            in.nextToken();
            int type = (int) in.nval;
            in.nextToken();
            int l = (int) in.nval - 1;
            in.nextToken();
            int r = (int) in.nval - 1;
            if (type == 1) {
                in.nextToken();
                update(1, 0, n - 1, l, r, (long) in.nval);
            } else {
                out.append(query(1, 0, n - 1, l, r)).append('\n');
            }
        }
        System.out.print(out);
    }
}

