#include <bits/stdc++.h>
using namespace std;

int n, q;
vector<long long> a, tree_, lazy_;

void build(int node, int lo, int hi) {
    if (lo == hi) { tree_[node] = a[lo]; return; }
    int mid = (lo + hi) / 2;
    build(2 * node, lo, mid);
    build(2 * node + 1, mid + 1, hi);
    tree_[node] = tree_[2 * node] + tree_[2 * node + 1];
}
void apply(int node, int lo, int hi, long long v) {
    tree_[node] += v * (hi - lo + 1);
    lazy_[node] += v;
}
void push(int node, int lo, int hi) {
    if (lazy_[node] != 0) {
        int mid = (lo + hi) / 2;
        apply(2 * node, lo, mid, lazy_[node]);
        apply(2 * node + 1, mid + 1, hi, lazy_[node]);
        lazy_[node] = 0;
    }
}
void update(int node, int lo, int hi, int l, int r, long long v) {
    if (r < lo || hi < l) return;
    if (l <= lo && hi <= r) { apply(node, lo, hi, v); return; }
    push(node, lo, hi);
    int mid = (lo + hi) / 2;
    update(2 * node, lo, mid, l, r, v);
    update(2 * node + 1, mid + 1, hi, l, r, v);
    tree_[node] = tree_[2 * node] + tree_[2 * node + 1];
}
long long query(int node, int lo, int hi, int l, int r) {
    if (r < lo || hi < l) return 0;
    if (l <= lo && hi <= r) return tree_[node];
    push(node, lo, hi);
    int mid = (lo + hi) / 2;
    return query(2 * node, lo, mid, l, r) + query(2 * node + 1, mid + 1, hi, l, r);
}

int main() {
    scanf("%d %d", &n, &q);
    a.assign(n, 0);
    for (auto& x : a) scanf("%lld", &x);
    tree_.assign(4 * n, 0);
    lazy_.assign(4 * n, 0);
    build(1, 0, n - 1);
    while (q--) {
        int t, l, r;
        scanf("%d %d %d", &t, &l, &r);
        l--; r--;
        if (t == 1) {
            long long v;
            scanf("%lld", &v);
            update(1, 0, n - 1, l, r, v);
        } else {
            printf("%lld\n", query(1, 0, n - 1, l, r));
        }
    }
    return 0;
}
